package br.com.eulopeesz.revminions;
import org.bukkit.*;import org.bukkit.command.CommandSender;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.scheduler.BukkitTask;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;

/** RevMinions, desenvolvido por eulopeesz. */
public final class RevMinionsPlugin extends JavaPlugin {
    public volatile Configs cfg;public Model state;public SignedItems signed;public Integrations integration;public Entities entities;public Combat combat;public Menus menus;public boolean ready;
    private Persistence storage;private ExecutorService io;private BukkitTask loop,autosave;private boolean modified,stopping,inFlight;private volatile String recovery;private String storageSignature;
    public final Map<UUID,Prompt> prompts=new ConcurrentHashMap<>();public static final class Prompt{public final UUID minion;public final String type;public final long expires=System.currentTimeMillis()+60000;Prompt(UUID minion,String type){this.minion=minion;this.type=type;}}
    public void onEnable(){try{
        cfg=new Configs(this);storageSignature=signature(cfg);signed=new SignedItems(this);entities=new Entities(this);combat=new Combat(this);menus=new Menus(this);Commands commands=new Commands(this);getCommand("minions").setExecutor(commands);getCommand("minions").setTabCompleter(commands);Bukkit.getPluginManager().registerEvents(new Events(this),this);
        io=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"RevMinions-IO");t.setDaemon(true);return t;});io.submit(()->{try{storage=new Persistence(this,cfg);final Model loaded=Persistence.decode(storage.load());if(stopping)return;Bukkit.getScheduler().runTask(this,()->initialize(loaded,0));}catch(Exception e){error(e);if(!stopping)Bukkit.getScheduler().runTask(this,()->Bukkit.getPluginManager().disablePlugin(this));}});
    }catch(Exception e){getLogger().severe(e.toString());Bukkit.getPluginManager().disablePlugin(this);}}
    private void initialize(Model loaded,int tries){try{
        integration=new Integrations(this);state=loaded;for(Model.Minion m:state.minions.values())normalize(m);for(World w:Bukkit.getWorlds())for(Chunk c:w.getLoadedChunks())entities.clearChunk(c);for(Player x:Bukkit.getOnlinePlayers())profile(x);ready=true;tasks();modified=true;log("console.inicio");
    }catch(Exception e){if(tries<5){Bukkit.getScheduler().runTaskLater(this,()->initialize(loaded,tries+1),40);return;}error(e);Bukkit.getPluginManager().disablePlugin(this);}}
    private String signature(Configs c){return c.c().getString("armazenamento.tipo")+c.c().getConfigurationSection("mysql").getValues(true);}
    private void normalize(Model.Minion m){if(!cfg.ids("minions","minions").contains(m.type))return;m.level=Math.max(1,Math.min(m.level,cfg.f("minions").getInt("minions."+m.type+".evolucao.nivel-maximo")));m.sword=Math.max(1,Math.min(m.sword,cfg.f("sword").getInt("espada.nivel-maximo")));for(String id:new ArrayList<>(m.enchants.keySet()))m.enchants.put(id,Math.max(0,Math.min(m.enchant(id),cfg.f("sword").getInt("encantamentos."+id+".nivel-maximo"))));if(!cfg.ids("config","personalizacao.cores").contains(m.color))m.color="aqua";if(!cfg.ids("config","personalizacao.particulas").contains(m.particle))m.particle="nenhuma";}
    public void reload(CommandSender s){try{
        Configs next=new Configs(this);boolean db=!signature(next).equals(storageSignature);if(db){next.c().set("armazenamento.tipo",cfg.c().getString("armazenamento.tipo"));next.c().set("mysql",cfg.c().getConfigurationSection("mysql").getValues(true));}
        Configs old=cfg;cfg=next;try{integration=new Integrations(this);}catch(Exception e){cfg=old;throw e;}
        for(Player x:Bukkit.getOnlinePlayers())if(x.getOpenInventory().getTopInventory().getHolder() instanceof Menus.Holder)x.closeInventory();prompts.clear();combat.clear();entities.clear();for(Model.Minion m:state.minions.values())normalize(m);tasks();dirty();msg(s,"reload-ok");if(db)msg(s,"reload-storage");
    }catch(Exception e){msg(s,"reload-erro");error(e);}}
    private void tasks(){if(loop!=null)loop.cancel();if(autosave!=null)autosave.cancel();loop=Bukkit.getScheduler().runTaskTimer(this,()->{if(ready)try{combat.tick();}catch(Exception e){error(e);}},20,cfg.c().getLong("minions.intervalo-ticks"));autosave=Bukkit.getScheduler().runTaskTimer(this,this::save,cfg.c().getLong("armazenamento.autosave-segundos")*20,cfg.c().getLong("armazenamento.autosave-segundos")*20);}
    public Model.Profile profile(Player player){Model.Profile profile=state.players.get(player.getUniqueId());if(profile==null){profile=new Model.Profile(player.getUniqueId(),player.getName());state.players.put(profile.id,profile);}profile.name=player.getName();return profile;}
    public Model.Profile find(String name){for(Model.Profile x:state.players.values())if(x.name.equalsIgnoreCase(name))return x;return null;}
    public boolean access(Player player,Model.Minion m){return ready&&m.placed&&(m.owner.equals(player.getUniqueId())||m.friends.contains(player.getUniqueId()));}
    public void dirty(){modified=true;}
    private void save(){if(!ready||!modified||inFlight||stopping)return;String snapshot=Persistence.encode(state);modified=false;inFlight=true;io.submit(()->{boolean success=true;try{storage.save(snapshot);recovery=null;}catch(Exception e){recovery=snapshot;success=false;log("console.save-erro","erro",e.toString());}final boolean done=success;if(!stopping)Bukkit.getScheduler().runTask(this,()->{inFlight=false;if(!done)modified=true;});});}
    public void ask(Player player,Model.Minion minion,String type){prompts.put(player.getUniqueId(),new Prompt(minion.id,type));player.closeInventory();msg(player,type.equals("name")?"digite-nome":"digite-amigo");}
    public void answer(Player player,String answer,Prompt prompt){
        if(!ready||!player.isOnline())return;if(System.currentTimeMillis()>prompt.expires||answer.equalsIgnoreCase("cancelar")){msg(player,"cancelado");return;}Model.Minion m=state.minions.get(prompt.minion);if(m==null||!access(player,m)){msg(player,"minion-ausente");return;}
        if(prompt.type.equals("name")){if(!m.owner.equals(player.getUniqueId())&&!cfg.c().getBoolean("amigos.personalizar")){msg(player,"apenas-dono");return;}String name=ChatColor.stripColor(Configs.text(answer.trim()));if(name.isEmpty()||name.length()>cfg.c().getInt("personalizacao.nome-maximo")||name.chars().anyMatch(Character::isISOControl)){msg(player,"invalido");return;}m.name=name;msg(player,"personalizado");}
        else{if(!m.owner.equals(player.getUniqueId())){msg(player,"apenas-dono");return;}Model.Profile friend=find(answer.trim());if(friend==null||friend.id.equals(m.owner)||m.friends.contains(friend.id)||m.friends.size()>=cfg.c().getInt("amigos.maximo")){msg(player,"amigo-invalido");return;}m.friends.add(friend.id);msg(player,"amigo-adicionado","player",friend.name);}
        dirty();menus.open(player,m,prompt.type.equals("name")?"personalizacao":"amigos");
    }
    public void activate(Player player,String[] tag){if(!ready){msg(player,"indisponivel");return;}Model.Profile profile=profile(player);String type=tag[0],id=tag[1];try{
        if(type.equals("gemas")){long n=Long.parseLong(id);profile.gems=Model.add(profile.gems,n);signed.consume(player);msg(player,"gemas-saldo","gemas",""+profile.gems);dirty();return;}
        boolean duplicate;if(type.equals("rgb"))duplicate=profile.rgb;else if(type.equals("cor")||type.equals("particula")){String path="personalizacao."+(type.equals("cor")?"cores":"particulas");if(!cfg.ids("config",path).contains(id)){msg(player,"invalido");return;}duplicate=(type.equals("cor")?profile.colors:profile.particles).contains(id);}else return;
        if(duplicate){msg(player,"ja-desbloqueado");return;}signed.consume(player);if(type.equals("rgb"))profile.rgb=true;else(type.equals("cor")?profile.colors:profile.particles).add(id);dirty();msg(player,"desbloqueado");
    }catch(ArithmeticException|IllegalArgumentException e){msg(player,"invalido");}}
    public void place(Player player,String[] tag,Location location){
        if(!ready){msg(player,"indisponivel");return;}if(!player.hasPermission(cfg.c().getString("minions.permissao-colocar"))){msg(player,"sem-permissao");return;}
        Model.Minion minion=null;String type=tag[1];if(tag[0].equals("placed")){try{minion=state.minions.get(UUID.fromString(type));}catch(IllegalArgumentException e){}if(minion==null||minion.placed||!minion.owner.equals(player.getUniqueId())){msg(player,"minion-ausente");return;}type=minion.type;}
        if(!cfg.ids("minions","minions").contains(type)){msg(player,"invalido");return;}if(!player.hasPermission(cfg.f("minions").getString("minions."+type+".permissao"))){msg(player,"sem-permissao");return;}
        if(!cfg.c().getStringList("minions.mundos").contains(location.getWorld().getName())||!integration.owns(player.getUniqueId(),location)||location.getBlock().getType()!=Material.AIR||location.clone().add(0,1,0).getBlock().getType()!=Material.AIR){msg(player,"local-invalido");return;}
        long count=state.minions.values().stream().filter(m->m.placed&&m.owner.equals(player.getUniqueId())).count();int limit=cfg.placementLimit(player::hasPermission);if(count>=limit){msg(player,"limite");return;}
        for(Model.Minion m:state.minions.values())if(m.placed&&m.world.equals(location.getWorld().getName())&&new Location(location.getWorld(),m.x,m.y,m.z).distanceSquared(location)<0.5){msg(player,"local-invalido");return;}
        if(minion==null){minion=new Model.Minion(UUID.randomUUID());minion.owner=player.getUniqueId();minion.type=type;minion.name=cfg.f("minions").getString("minions."+type+".nome");minion.color=cfg.f("minions").getString("minions."+type+".roupa.cor");state.minions.put(minion.id,minion);}minion.placed=true;minion.world=location.getWorld().getName();minion.x=location.getX();minion.y=location.getY();minion.z=location.getZ();minion.yaw=player.getLocation().getYaw();profile(player);signed.consume(player);entities.spawn(minion);dirty();msg(player,"colocado");
    }
    public void msg(CommandSender sender,String key,String...values){if(cfg==null)return;Map<String,String> vars=new HashMap<>();for(int i=0;i+1<values.length;i+=2)vars.put(values[i],values[i+1]);Object o=cfg.f("messages").get(key);if(o instanceof List)for(String line:cfg.f("messages").getStringList(key))sender.sendMessage(cfg.render(line,vars));else if(o instanceof String)sender.sendMessage(cfg.render((String)o,vars));}
    public void log(String key,String...values){if(cfg==null)return;Map<String,String> vars=new HashMap<>();for(int i=0;i+1<values.length;i+=2)vars.put(values[i],values[i+1]);getLogger().info(cfg.render(cfg.f("messages").getString(key,""),vars));}
    public void error(Exception e){log("console.erro","erro",e.toString());}
    public void onDisable(){stopping=true;ready=false;if(combat!=null)combat.clear();if(entities!=null)entities.clear();if(io==null)return;
        if(state!=null&&storage!=null){String latest=Persistence.encode(state);io.submit(()->{try{storage.save(latest);recovery=null;}catch(Exception e){recovery=latest;log("console.save-erro","erro",e.toString());}});}
        io.submit(()->{if(recovery!=null)try{Files.write(getDataFolder().toPath().resolve("recovery.yml"),recovery.getBytes(StandardCharsets.UTF_8));}catch(Exception e){error(e);}if(storage!=null)storage.close();});io.shutdown();try{if(!io.awaitTermination(30,TimeUnit.SECONDS))error(new Exception("IO timeout"));}catch(InterruptedException e){Thread.currentThread().interrupt();}}
}
